INSERT INTO `wp_postmeta` VALUES (1,2,'_wp_page_template','default'),(2,3,'_wp_page_template','default'),(3,5,'_form','<label> 氏名\n    [text* your-name] </label>\n\n<label> メールアドレス\n    [email* your-email] </label>\n\n<label> 題名\n    [text* your-subject] </label>\n\n<label> メッセージ本文 (任意)\n    [textarea your-message] </label>\n\n[submit \"送信\"]'),(4,5,'_mail','a:9:{s:6:\"active\";b:1;s:7:\"subject\";s:30:\"[_site_title] \"[your-subject]\"\";s:6:\"sender\";s:37:\"[_site_title] <wordpress@example.com>\";s:9:\"recipient\";s:19:\"[_site_admin_email]\";s:4:\"body\";s:212:\"差出人: [your-name] <[your-email]>\n題名: [your-subject]\n\nメッセージ本文:\n[your-message]\n\n-- \nこのメールは [_site_title] ([_site_url]) のお問い合わせフォームから送信されました\";s:18:\"additional_headers\";s:22:\"Reply-To: [your-email]\";s:11:\"attachments\";s:0:\"\";s:8:\"use_html\";b:0;s:13:\"exclude_blank\";b:0;}'),(5,5,'_mail_2','a:9:{s:6:\"active\";b:0;s:7:\"subject\";s:30:\"[_site_title] \"[your-subject]\"\";s:6:\"sender\";s:27:\"[_site_title] <wordpress@_>\";s:9:\"recipient\";s:12:\"[your-email]\";s:4:\"body\";s:150:\"メッセージ本文:\n[your-message]\n\n-- \nこのメールは [_site_title] ([_site_url]) のお問い合わせフォームから送信されました\";s:18:\"additional_headers\";s:29:\"Reply-To: [_site_admin_email]\";s:11:\"attachments\";s:0:\"\";s:8:\"use_html\";b:0;s:13:\"exclude_blank\";b:0;}'),(6,5,'_messages','a:22:{s:12:\"mail_sent_ok\";s:75:\"ありがとうございます。メッセージは送信されました。\";s:12:\"mail_sent_ng\";s:84:\"メッセージの送信に失敗しました。後でまたお試しください。\";s:16:\"validation_error\";s:81:\"入力内容に問題があります。確認して再度お試しください。\";s:4:\"spam\";s:84:\"メッセージの送信に失敗しました。後でまたお試しください。\";s:12:\"accept_terms\";s:66:\"メッセージを送信する前に承諾確認が必要です。\";s:16:\"invalid_required\";s:42:\"必須項目に入力してください。\";s:16:\"invalid_too_long\";s:48:\"入力されたテキストが長すぎます。\";s:17:\"invalid_too_short\";s:48:\"入力されたテキストが短すぎます。\";s:13:\"upload_failed\";s:81:\"ファイルのアップロード時に不明なエラーが発生しました。\";s:24:\"upload_file_type_invalid\";s:66:\"この形式のファイルはアップロードできません。\";s:21:\"upload_file_too_large\";s:36:\"ファイルが大きすぎます。\";s:23:\"upload_failed_php_error\";s:72:\"ファイルのアップロード中にエラーが発生しました。\";s:12:\"invalid_date\";s:59:\"YYYY-MM-DD の形式で日付を入力してください。\";s:14:\"date_too_early\";s:42:\"入力された日付が早すぎます。\";s:13:\"date_too_late\";s:42:\"入力された日付が遅すぎます。\";s:14:\"invalid_number\";s:36:\"数値を入力してください。\";s:16:\"number_too_small\";s:45:\"入力された数値が小さすぎます。\";s:16:\"number_too_large\";s:45:\"入力された数値が大きすぎます。\";s:23:\"quiz_answer_not_correct\";s:48:\"クイズの答えが正しくありません。\";s:13:\"invalid_email\";s:51:\"メールアドレスを入力してください。\";s:11:\"invalid_url\";s:34:\"URL を入力してください。\";s:11:\"invalid_tel\";s:42:\"電話番号を入力してください。\";}'),(7,5,'_additional_settings',''),(8,5,'_locale','ja'),(9,5,'_hash','a1e2646cb3e2378b74e52d628ef349560ae050c1'),(11,5,'_config_validation','a:1:{s:11:\"mail.sender\";a:1:{i:0;a:2:{s:4:\"code\";s:24:\"email_not_in_site_domain\";s:4:\"args\";a:3:{s:7:\"message\";s:108:\"サイトのドメインに属していないメールアドレスが送信元に設定されています。\";s:6:\"params\";a:0:{}s:4:\"link\";s:70:\"https://contactform7.com/configuration-errors/email-not-in-site-domain\";}}}}'),(18,1,'_edit_lock','1749477264:1'),(19,2,'_edit_lock','1749474976:1'),(22,3,'_wp_suggested_privacy_policy_content','a:3:{s:11:\"plugin_name\";s:9:\"WordPress\";s:11:\"policy_text\";s:5771:\"<h2 class=\"wp-block-heading\">私たちについて</h2><p><strong class=\"privacy-policy-tutorial\">提案テキスト: </strong>私たちのサイトアドレスは https://lvh.me です。</p><h2 class=\"wp-block-heading\">コメント</h2><p><strong class=\"privacy-policy-tutorial\">提案テキスト: </strong>訪問者がこのサイトにコメントを残す際、コメントフォームに表示されているデータ、そしてスパム検出に役立てるための IP アドレスとブラウザーユーザーエージェント文字列を収集します。</p><p>メールアドレスから作成される匿名化された (「ハッシュ」とも呼ばれる) 文字列は、あなたが Gravatar サービスを使用中かどうか確認するため同サービスに提供されることがあります。同サービスのプライバシーポリシーは https://automattic.com/privacy/ にあります。コメントが承認されると、プロフィール画像がコメントとともに一般公開されます。</p><h2 class=\"wp-block-heading\">メディア</h2><p><strong class=\"privacy-policy-tutorial\">提案テキスト: </strong>サイトに画像をアップロードする際、位置情報 (EXIF GPS) を含む画像をアップロードするべきではありません。サイトの訪問者は、サイトから画像をダウンロードして位置データを抽出することができます。</p><h2 class=\"wp-block-heading\">Cookie</h2><p><strong class=\"privacy-policy-tutorial\">提案テキスト: </strong>サイトにコメントを残す際、お名前、メールアドレス、サイトを Cookie に保存することにオプトインできます。これはあなたの便宜のためであり、他のコメントを残す際に詳細情報を再入力する手間を省きます。この Cookie は1年間保持されます。</p><p>ログインページを訪問すると、お使いのブラウザーが Cookie を受け入れられるかを判断するために一時 Cookie を設定します。この Cookie は個人データを含んでおらず、ブラウザーを閉じると廃棄されます。</p><p>ログインの際さらに、ログイン情報と画面表示情報を保持するため、私たちはいくつかの Cookie を設定します。ログイン Cookie は2日間、画面表示オプション Cookie は1年間保持されます。「ログイン状態を保存する」を選択した場合、ログイン情報は2週間維持されます。ログアウトするとログイン Cookie は消去されます。</p><p>もし投稿を編集または公開すると、さらなる Cookie がブラウザーに保存されます。この Cookie は個人データを含まず、単に変更した投稿の ID を示すものです。1日で有効期限が切れます。</p><h2 class=\"wp-block-heading\">他サイトからの埋め込みコンテンツ</h2><p><strong class=\"privacy-policy-tutorial\">提案テキスト: </strong>このサイトの投稿には埋め込みコンテンツ (動画、画像、投稿など) が含まれます。他サイトからの埋め込みコンテンツは、訪問者がそのサイトを訪れた場合とまったく同じように振る舞います。</p><p>これらのサイトは、あなたのデータの収集、Cookie の使用、サードパーティによる追加トラッキングの埋め込み、埋め込みコンテンツとのやりとりの監視を行うことがあります。アカウントを使ってそのサイトにログイン中の場合、埋め込みコンテンツとのやりとりのトラッキングも含まれます。</p><h2 class=\"wp-block-heading\">あなたのデータの共有先</h2><p><strong class=\"privacy-policy-tutorial\">提案テキスト: </strong>パスワードリセットをリクエストすると、IP アドレスがリセット用のメールに含まれます。</p><h2 class=\"wp-block-heading\">データを保存する期間</h2><p><strong class=\"privacy-policy-tutorial\">提案テキスト: </strong>あなたがコメントを残すと、コメントとそのメタデータが無期限に保持されます。これは、モデレーションキューにコメントを保持しておく代わりに、フォローアップのコメントを自動的に認識し承認できるようにするためです。</p><p>このサイトに登録したユーザーがいる場合、その方がユーザープロフィールページで提供した個人情報を保存します。すべてのユーザーは自分の個人情報を表示、編集、削除することができます (ただしユーザー名は変更することができません)。サイト管理者もそれらの情報を表示、編集できます。</p><h2 class=\"wp-block-heading\">データに対するあなたの権利</h2><p><strong class=\"privacy-policy-tutorial\">提案テキスト: </strong>このサイトのアカウントを持っているか、サイトにコメントを残したことがある場合、私たちが保持するあなたについての個人データ (提供したすべてのデータを含む) をエクスポートファイルとして受け取るリクエストを行うことができます。また、個人データの消去リクエストを行うこともできます。これには、管理、法律、セキュリティ目的のために保持する義務があるデータは含まれません。</p><h2 class=\"wp-block-heading\">どこにあなたのデータが送られるか</h2><p><strong class=\"privacy-policy-tutorial\">提案テキスト: </strong>訪問者によるコメントは、自動スパム検出サービスを通じて確認を行う場合があります。</p>\";s:5:\"added\";i:1733408750;}'),(23,3,'_wp_suggested_privacy_policy_content','a:3:{s:11:\"plugin_name\";s:7:\"Akismet\";s:11:\"policy_text\";s:516:\"このサイトでは Akismet アンチスパムサービスを通じて、サイトにコメントする訪問者に関する情報を収集します。収集する情報はユーザーの Akismet 設定によって異なりますが、通常、コメント投稿者の IP アドレス、ユーザーエージェント、リファラー、サイト URL (さらにコメント投稿者が直接提供するその他の情報。例えば氏名、ユーザー名、メールアドレス、コメント本文など) 。\";s:5:\"added\";i:1733408750;}'),(34,30,'_edit_last','1'),(35,30,'_edit_lock','1746162252:1'),(36,30,'_wp_old_slug','%e3%82%a4%e3%83%99%e3%83%b3%e3%83%88-bbq'),(38,33,'_edit_lock','1746162380:1'),(39,33,'_edit_last','1'),(46,37,'_edit_lock','1749466407:1'),(47,40,'reservation_name','鈴木'),(48,40,'reservation_email','suzuki@example.com'),(49,40,'reservation_count','2'),(50,41,'reservation_name','鈴木太郎'),(51,41,'reservation_email','suzuki@example.com'),(52,41,'reservation_count','2'),(53,42,'reservation_name','鈴木太郎'),(54,42,'reservation_email','suzuki@example.com'),(55,42,'reservation_count','2'),(56,42,'_edit_lock','1746164665:1'),(57,43,'_reservation_name','鈴木'),(58,43,'_reservation_email','suzuki@example.com'),(59,43,'_reservation_count','2'),(60,43,'_edit_lock','1746164811:1'),(61,45,'_um_custom_fields','a:6:{s:10:\"user_login\";a:15:{s:5:\"title\";s:8:\"Username\";s:7:\"metakey\";s:10:\"user_login\";s:4:\"type\";s:4:\"text\";s:5:\"label\";s:8:\"Username\";s:8:\"required\";i:1;s:6:\"public\";i:1;s:8:\"editable\";b:0;s:8:\"validate\";s:15:\"unique_username\";s:9:\"min_chars\";i:3;s:9:\"max_chars\";i:24;s:8:\"position\";i:1;s:6:\"in_row\";s:9:\"_um_row_1\";s:10:\"in_sub_row\";s:1:\"0\";s:9:\"in_column\";i:1;s:8:\"in_group\";s:0:\"\";}s:10:\"user_email\";a:13:{s:5:\"title\";s:14:\"E-mail Address\";s:7:\"metakey\";s:10:\"user_email\";s:4:\"type\";s:4:\"text\";s:5:\"label\";s:14:\"E-mail Address\";s:8:\"required\";i:0;s:6:\"public\";i:1;s:8:\"editable\";b:1;s:8:\"validate\";s:12:\"unique_email\";s:8:\"position\";i:4;s:6:\"in_row\";s:9:\"_um_row_1\";s:10:\"in_sub_row\";s:1:\"0\";s:9:\"in_column\";i:1;s:8:\"in_group\";s:0:\"\";}s:13:\"user_password\";a:16:{s:5:\"title\";s:8:\"Password\";s:7:\"metakey\";s:13:\"user_password\";s:4:\"type\";s:8:\"password\";s:5:\"label\";s:8:\"Password\";s:8:\"required\";i:1;s:6:\"p