--
-- Table structure for table `wp_rcp_customers`
--

DROP TABLE IF EXISTS `wp_rcp_customers`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `wp_rcp_customers` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint unsigned NOT NULL DEFAULT '0',
  `date_registered` datetime NOT NULL,
  `email_verification` enum('verified','pending','none') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci DEFAULT 'none',
  `last_login` datetime DEFAULT NULL,
  `has_trialed` smallint unsigned DEFAULT NULL,
  `ips` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `notes` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `uuid` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_520_ci NOT NULL DEFAULT '',
  PRIMARY KEY (`id`),
  KEY `user_id` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_520_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

